arguments.cmd:
mkdir -p /app/output && cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Leap Studio — Reinvention & Experience Partner</title>
  <meta name="description" content="Leap Studio is a global creative agency reinventing enterprise experiences through design, strategy, and technology." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: #0a0a0a;
      --bg-soft: #121212;
      --surface: #161616;
      --surface-2: #1c1c1c;
      --text: #f4f4f4;
      --text-dim: #b4b4b4;
      --line: #2a2a2a;
      --blue: #3b82f6;
      --amber: #f59e0b;
      --radius: 18px;
      --max: 1200px;
      --section-pad: clamp(64px, 9vw, 120px);
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
      background: radial-gradient(1200px 800px at 100% -5%, #162445 0%, var(--bg) 50%), var(--bg);
      color: var(--text);
      line-height: 1.5;
      overflow-x: hidden;
    }

    img { max-width: 100%; display: block; }
    a { color: inherit; text-decoration: none; }

    .container { width: min(92%, var(--max)); margin: 0 auto; }
    .section { padding: var(--section-pad) 0; }
    .eyebrow { font-size: 12px; text-transform: uppercase; letter-spacing: 0.14em; color: var(--text-dim); }

    header {
      position: sticky;
      top: 0;
      z-index: 60;
      backdrop-filter: blur(12px);
      background: rgba(10, 10, 10, 0.82);
      border-bottom: 1px solid rgba(255, 255, 255, 0.07);
    }

    .nav {
      min-height: 76px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
    }

    .brand {
      font-weight: 800;
      letter-spacing: 0.02em;
      font-size: 1.12rem;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: clamp(12px, 2vw, 24px);
      font-size: 0.95rem;
      color: #d8d8d8;
    }

    .nav-links a { transition: color .2s ease; }
    .nav-links a:hover { color: #fff; }

    .lang-wrap { position: relative; }
    .lang-btn {
      background: var(--surface);
      border: 1px solid var(--line);
      color: #fff;
      padding: 9px 12px;
      border-radius: 999px;
      font-size: 0.86rem;
      cursor: pointer;
    }

    .lang-menu {
      position: absolute;
      right: 0;
      margin-top: 10px;
      min-width: 170px;
      background: #121212;
      border: 1px solid var(--line);
      border-radius: 12px;
      padding: 8px;
      display: none;
      box-shadow: 0 16px 30px rgba(0,0,0,.35);
    }

    .lang-menu.open { display: block; }
    .lang-menu button {
      width: 100%;
      text-align: left;
      background: transparent;
      color: var(--text);
      border: 0;
      padding: 10px;
      border-radius: 8px;
      cursor: pointer;
    }

    .lang-menu button:hover { background: #1f1f1f; }

    .menu-toggle {
      display: none;
      background: transparent;
      border: 1px solid var(--line);
      color: var(--text);
      padding: 8px 10px;
      border-radius: 10px;
    }

    .hero { padding-top: clamp(48px, 8vw, 96px); }
    .hero-grid {
      display: grid;
      grid-template-columns: 1.1fr 1fr;
      gap: clamp(24px, 4vw, 56px);
      align-items: end;
    }

    h1 {
      font-size: clamp(2.3rem, 6.5vw, 5.1rem);
      line-height: 0.96;
      margin: 10px 0 20px;
      letter-spacing: -0.025em;
      max-width: 12ch;
    }

    .lead {
      color: var(--text-dim);
      max-width: 52ch;
      font-size: clamp(1rem, 1.6vw, 1.2rem);
    }

    .hero-carousel {
      position: relative;
      border: 1px solid var(--line);
      border-radius: var(--radius);
      background: linear-gradient(180deg, #161616 0%, #101010 100%);
      overflow: hidden;
      min-height: 360px;
    }

    .hero-track {
      display: flex;
      width: 100%;
      transition: transform .5s ease;
      touch-action: pan-y;
    }

    .hero-slide {
      min-width: 100%;
      padding: 28px;
      display: grid;
      gap: 18px;
      align-content: space-between;
    }

    .hero-card-media {
      height: 180px;
      border-radius: 14px;
      overflow: hidden;
      background-size: cover;
      background-position: center;
      filter: saturate(0.8);
    }

    .hero-slide h3 { margin: 0; font-size: 1.25rem; }
    .hero-slide p { margin: 0; color: var(--text-dim); }

    .carousel-controls {
      position: absolute;
      left: 18px;
      bottom: 18px;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .ctrl-btn {
      width: 34px;
      height: 34px;
      border-radius: 999px;
      border: 1px solid #3a3a3a;
      background: rgba(255,255,255,.05);
      color: #fff;
      cursor: pointer;
    }

    .dots { display: flex; gap: 8px; margin-left: 8px; }
    .dot {
      width: 8px;
      height: 8px;
      border-radius: 999px;
      background: #565656;
      border: 0;
      padding: 0;
      cursor: pointer;
    }
    .dot.active { background: var(--blue); }

    .section-head {
      display: flex;
      justify-content: space-between;
      align-items: end;
      gap: 18px;
      margin-bottom: 26px;
    }

    h2 {
      margin: 8px 0 0;
      font-size: clamp(1.5rem, 4vw, 3rem);
      letter-spacing: -0.02em;
      line-height: 1.05;
    }

    .region-tabs {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
    }

    .tab {
      border: 1px solid var(--line);
      background: #121212;
      color: #d8d8d8;
      padding: 9px 14px;
      border-radius: 999px;
      cursor: pointer;
    }

    .tab.active {
      border-color: var(--blue);
      color: #fff;
      background: rgba(59,130,246,.12);
    }

    .team-carousel {
      position: relative;
      overflow: hidden;
    }

    .team-track {
      display: flex;
      gap: 14px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      padding-bottom: 6px;
      scrollbar-width: thin;
      scrollbar-color: #3a3a3a transparent;
    }

    .team-card {
      min-width: clamp(250px, 35vw, 320px);
      max-width: 320px;
      background: linear-gradient(180deg, #171717 0%, #101010 100%);
      border: 1px solid var(--line);
      border-radius: 16px;
      overflow: hidden;
      scroll-snap-align: start;
    }

    .team-photo {
      height: 220px;
      background-size: cover;
      background-position: center;
      filter: grayscale(0.1) contrast(1.05);
    }

    .team-content { padding: 16px; }
    .team-quote { color: #d2d2d2; margin: 0 0 14px; font-size: .97rem; }
    .team-name { margin: 0; font-weight: 700; }
    .team-meta { color: var(--text-dim); margin: 3px 0; font-size: .9rem; }
    .team-office { color: var(--blue); font-size: .86rem; }

    .horizontal-scroll {
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: minmax(260px, 1fr);
      gap: 14px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      padding-bottom: 8px;
    }

    .project-card, .insight-card {
      border: 1px solid var(--line);
      border-radius: 16px;
      overflow: hidden;
      background: #121212;
      scroll-snap-align: start;
    }

    .project-thumb, .insight-thumb {
      height: 170px;
      background-size: cover;
      background-position: center;
      filter: saturate(.7) brightness(.8);
    }

    .project-body, .insight-body { padding: 14px; }
    .project-body h3, .insight-body h3 {
      margin: 0;
      font-size: 1.02rem;
      line-height: 1.25;
    }

    .cta-banner {
      border: 1px solid rgba(245,158,11,.35);
      background: linear-gradient(100deg, rgba(245,158,11,.11), rgba(59,130,246,.09));
      border-radius: 20px;
      padding: clamp(24px, 4vw, 44px);
    }

    .cta-banner h2 { margin-top: 0; max-width: 17ch; }
    .cta-btn {
      margin-top: 16px;
      background: #fff;
      color: #121212;
      border: 0;
      padding: 12px 18px;
      border-radius: 999px;
      font-weight: 600;
      cursor: pointer;
    }

    .cards-4 {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 14px;
    }

    .panel {
      border: 1px solid var(--line);
      background: #121212;
      border-radius: 14px;
      padding: 18px;
    }

    .panel h3 { margin-top: 0; font-size: 1rem; }
    .panel p { margin: 0; color: var(--text-dim); font-size: .95rem; }

    footer {
      border-top: 1px solid var(--line);
      padding: 30px 0 50px;
      color: var(--text-dim);
      font-size: .9rem;
    }

    .footer-grid {
      display: flex;
      justify-content: space-between;
      gap: 20px;
      flex-wrap: wrap;
    }

    .cookie-banner {
      position: fixed;
      bottom: 18px;
      right: 18px;
      left: 18px;
      max-width: 740px;
      margin: 0 auto;
      z-index: 80;
      border: 1px solid var(--line);
      background: rgba(17,17,17,.98);
      border-radius: 14px;
      padding: 14px;
      display: none;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      flex-wrap: wrap;
    }

    .cookie-banner.show { display: flex; }

    .cookie-actions {
      display: flex;
      gap: 8px;
      flex-wrap: wrap;
    }

    .cookie-actions button {
      border: 1px solid var(--line);
      padding: 9px 12px;
      border-radius: 999px;
      background: #171717;
      color: #fff;
      cursor: pointer;
    }

    .cookie-actions .primary {
      background: var(--blue);
      border-color: #4f8dff;
    }

    @media (max-width: 980px) {
      .hero-grid { grid-template-columns: 1fr; }
      .cards-4 { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .nav-links {
        position: absolute;
        left: 0;
        right: 0;
        top: 76px;
        background: rgba(10,10,10,.96);
        border-bottom: 1px solid var(--line);
        padding: 16px 4%;
        display: none;
        flex-wrap: wrap;
      }
      .nav-links.open { display: flex; }
      .menu-toggle { display: inline-flex; }
    }

    @media (max-width: 640px) {
      .cards-4 { grid-template-columns: 1fr; }
      .horizontal-scroll { grid-auto-columns: 82%; }
      .team-card { min-width: 82%; }
      .hero-carousel { min-height: 340px; }
    }
  </style>
</head>
<body>
  <header>
    <div class="container nav">
      <a href="#" class="brand">Leap Studio</a>
      <button class="menu-toggle" aria-label="Toggle menu">☰</button>
      <nav class="nav-links" id="navLinks">
        <a href="#insights">Insights</a>
        <a href="#work">Work</a>
        <a href="#how">Services</a>
        <a href="#principles">Culture</a>
        <a href="#cta">Make Your Mark</a>
        <a href="#footer">Contact Us</a>
        <div class="lang-wrap">
          <button class="lang-btn" id="langBtn" aria-expanded="false">Global EN ▾</button>
          <div class="lang-menu" id="langMenu" role="menu">
            <button type="button">Global EN</button>
            <button type="button">France FR</button>
            <button type="button">China CN</button>
          </div>
        </div>
      </nav>
    </div>
  </header>

  <main>
    <section class="hero section" id="home">
      <div class="container hero-grid">
        <div>
          <p class="eyebrow">Global Reinvention Partner</p>
          <h1>Designing what enterprise transformation feels like.</h1>
          <p class="lead">Leap Studio fuses strategy, creativity, and emerging technology to reinvent experiences for the world’s most ambitious organizations.</p>
        </div>

        <div class="hero-carousel" aria-label="Featured content carousel">
          <div class="hero-track" id="heroTrack">
            <article class="hero-slide">
              <div class="hero-card-media" style="background-image:url('https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=1200&q=80');"></div>
              <div>
                <p class="eyebrow">Featured Report</p>
                <h3>When Human Connection Meets AI</h3>
                <p>How category-leading brands orchestrate machine intelligence and emotional design to create meaningful customer moments.</p>
              </div>
            </article>
            <article class="hero-slide">
              <div class="hero-card-media" style="background-image:url('https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=1200&q=80');"></div>
              <div>
                <p class="eyebrow">Client Story</p>
                <h3>Modernizing the Point-of-Sale Experience</h3>
                <p>A global retail rollout reducing friction across in-store journeys while elevating brand consistency.</p>
              </div>
            </article>
            <article class="hero-slide">
              <div class="hero-card-media" style="background-image:url('https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=1200&q=80');"></div>
              <div>
                <p class="eyebrow">Podcast Episode</p>
                <h3>Writing the Future of AI</h3>
                <p>Leaders discuss governance, design ethics, and practical pathways for enterprise-scale innovation.</p>
              </div>
            </article>
          </div>
          <div class="carousel-controls">
            <button class="ctrl-btn" id="heroPrev" aria-label="Previous slide">←</button>
            <button class="ctrl-btn" id="heroNext" aria-label="Next slide">→</button>
            <div class="dots" id="heroDots"></div>
          </div>
        </div>
      </div>
    </section>

    <section class="section" id="team">
      <div class="container">
        <div class="section-head">
          <div>
            <p class="eyebrow">Global Studios</p>
            <h2>Teams shaping bold work worldwide.</h2>
          </div>
          <div class="region-tabs" id="regionTabs">
            <button class="tab active" data-region="North America">North America</button>
            <button class="tab" data-region="Asia">Asia</button>
            <button class="tab" data-region="Europe">Europe</button>
            <button class="tab" data-region="Oceania">Oceania</button>
          </div>
        </div>
        <div class="team-carousel">
          <div class="team-track" id="teamTrack"></div>
        </div>
      </div>
    </section>

    <section class="section" id="work">
      <div class="container">
        <div class="section-head">
          <div>
            <p class="eyebrow">Client Work</p>
            <h2>Enterprise outcomes, crafted with imagination.</h2>
          </div>
        </div>
        <div class="horizontal-scroll" id="workTrack"></div>
      </div>
    </section>

    <section class="section" id="cta">
      <div class="container cta-banner">
        <p class="eyebrow">Partnership</p>
        <h2>Build what your industry hasn’t seen yet.</h2>
        <p class="lead">From AI-enabled service ecosystems to iconic digital products, Leap Studio helps enterprise teams move from complexity to clarity.</p>
        <button class="cta-btn">Start a Conversation</button>
      </div>
    </section>

    <section class="section" id="how">
      <div class="container">
        <div class="section-head">
          <div>
            <p class="eyebrow">How We Work</p>
            <h2>Integrated, iterative, relentlessly human.</h2>
          </div>
        </div>
        <div class="cards-4" id="howCards"></div>
      </div>
    </section>

    <section class="section" id="insights">
      <div class="container">
        <div class="section-head">
          <div>
            <p class="eyebrow">Latest Insights</p>
            <h2>Signals, stories, and strategic perspective.</h2>
          </div>
        </div>
        <div class="horizontal-scroll" id="insightsTrack"></div>
      </div>
    </section>

    <section class="section" id="principles">
      <div class="container">
        <div class="section-head">
          <div>
            <p class="eyebrow">Our Principles</p>
            <h2>Values that move ambitious teams forward.</h2>
          </div>
        </div>
        <div class="cards-4" id="principlesCards"></div>
      </div>
    </section>
  </main>

  <footer id="footer">
    <div class="container footer-grid">
      <div>
        <div class="brand">Leap Studio</div>
        <p>Reinvention and experience partner for modern enterprises.</p>
      </div>
      <div>
        <p>Studios: New York · San Francisco · London · Munich · Singapore · Melbourne</p>
        <p>© 2026 Leap Studio. All rights reserved.</p>
      </div>
    </div>
  </footer>

  <div class="cookie-banner" id="cookieBanner" role="dialog" aria-label="Cookie preferences">
    <div>
      <strong>Cookies at Leap Studio</strong><br>
      <span style="color:#c8c8c8">We use cookies to optimize site performance and tailor content.</span>
    </div>
    <div class="cookie-actions">
      <button type="button" class="primary" data-cookie="accept">Accept All</button>
      <button type="button" data-cookie="manage">Manage Settings</button>
      <button type="button" data-cookie="decline">Decline All</button>
    </div>
  </div>

  <script>
    const teamByRegion = {
      "North America": [
        { name: "Maya Rivera", title: "Executive Creative Director", office: "New York", quote: "We help legacy organizations feel radically relevant again.", img: "https://images.unsplash.com/photo-1487412720507-e7ab37603c6f?auto=format&fit=crop&w=800&q=80" },
        { name: "Jordan Lee", title: "Design Strategy Lead", office: "San Francisco", quote: "The best transformation programs are felt by customers first.", img: "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=800&q=80" }
      ],
      "Asia": [
        { name: "Priya Nair", title: "Innovation Partner", office: "Singapore", quote: "Regional nuance is where global brands win trust.", img: "https://images.unsplash.com/photo-1524504388940-b1c1722653e1?auto=format&fit=crop&w=800&q=80" },
        { name: "Kenji Watanabe", title: "Experience Architect", office: "Singapore", quote: "Precision and empathy can coexist in enterprise design.", img: "https://images.unsplash.com/photo-1542206395-9feb3edaa68d?auto=format&fit=crop&w=800&q=80" }
      ],
      "Europe": [
        { name: "Elena Weber", title: "Transformation Principal", office: "Munich", quote: "Impact comes from connecting operational change with human behavior.", img: "https://images.unsplash.com/photo-1488426862026-3ee34a7d66df?auto=format&fit=crop&w=800&q=80" },
        { name: "Oliver Grant", title: "Client Partner", office: "London", quote: "We scale craft without losing strategic clarity.", img: "https://images.unsplash.com/photo-1474176857210-7287d38d27c6?auto=format&fit=crop&w=800&q=80" }
      ],
      "Oceania": [
        { name: "Sophie Martin", title: "Service Design Director", office: "Melbourne", quote: "Every touchpoint should signal confidence and care.", img: "https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=800&q=80" },
        { name: "Liam Brooks", title: "Creative Technologist", office: "Melbourne", quote: "Prototype fast, then harden for enterprise reality.", img: "https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=800&q=80" }
      ]
    };

    const workProjects = [
      "Creating Consumer Insights at Scale",
      "Deepening Customer Engagement",
      "Harnessing Data for Leaner and Greener Future of Mobility",
      "Modernizing the Point-of-Sale Experience",
      "Reimagining Luxury Craftsmanship",
      "Helping Healthier Habits Stick"
    ];

    const insights = [
      "When Human Connection Meets AI",
      "Writing the Future of AI",
      "Amplifying Clinical Care with AI",
      "The Future of Customer Experience",
      "Next-Gen Contact Centers: Powered by AI",
      "From Complexity to Clarity"
    ];

    const principles = [
      "Challenge the status quo",
      "Fuse art & science to make ideas real",
      "Create a lasting impact at global scale",
      "Regenerate systems & communities"
    ];

    const howWeWork = [
      { title: "Discover", text: "Map customer realities, business constraints, and growth opportunities in one strategic view." },
      { title: "Design", text: "Translate insight into compelling service concepts, journeys, and digital products." },
      { title: "Build", text: "Prototype, validate, and ship with multidisciplinary squads embedded with client teams." },
      { title: "Scale", text: "Operationalize capability and governance so innovation endures across markets." }
    ];

    function cardImage(index) {
      const imgs = [
        "https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=1200&q=80",
        "https://images.unsplash.com/photo-1552664730-d307ca884978?auto=format&fit=crop&w=1200&q=80",
        "https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1200&q=80",
        "https://images.unsplash.com/photo-1551434678-e076c223a692?auto=format&fit=crop&w=1200&q=80",
        "https://images.unsplash.com/photo-1517048676732-d65bc937f952?auto=format&fit=crop&w=1200&q=80",
        "https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=1200&q=80"
      ];
      return imgs[index % imgs.length];
    }

    const teamTrack = document.getElementById('teamTrack');
    const regionTabs = document.getElementById('regionTabs');

    function renderTeam(region) {
      teamTrack.innerHTML = '';
      (teamByRegion[region] || []).forEach((member) => {
        const card = document.createElement('article');
        card.className = 'team-card';
        card.innerHTML = `
          <div class="team-photo" style="background-image:url('${member.img}')"></div>
          <div class="team-content">
            <p class="team-quote">“${member.quote}”</p>
            <p class="team-name">${member.name}</p>
            <p class="team-meta">${member.title}</p>
            <a href="#" class="team-office">${member.office} Office ↗</a>
          </div>
        `;
        teamTrack.appendChild(card);
      });
      teamTrack.scrollTo({ left: 0, behavior: 'smooth' });
    }

    regionTabs.addEventListener('click', (e) => {
      const btn = e.target.closest('.tab');
      if (!btn) return;
      [...regionTabs.querySelectorAll('.tab')].forEach(tab => tab.classList.remove('active'));
      btn.classList.add('active');
      renderTeam(btn.dataset.region);
    });

    renderTeam('North America');

    const workTrack = document.getElementById('workTrack');
    workProjects.forEach((title, idx) => {
      const item = document.createElement('article');
      item.className = 'project-card';
