        { name: "Oliver Grant", title: "Client Partner", office: "London", quote: "We scale craft without losing strategic clarity.", img: "https://images.unsplash.com/photo-1474176857210-7287d38d27c6?auto=format&fit=crop&w=800&q=80" }
      ],
      "Oceania": [
        { name: "Sophie Martin", title: "Service Design Director", office: "Melbourne", quote: "Every touchpoint should signal confidence and care.", img: "https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=800&q=80" },
        { name: "Liam Brooks", title: "Creative Technologist", office: "Melbourne", quote: "Prototype fast, then harden for enterprise reality.", img: "https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=800&q=80" }
      ]
    };

    const workProjects = [
      "Creating Consumer Insights at Scale",
      "Deepening Customer Engagement",
      "Harnessing Data for Leaner and Greener Future of Mobility",
      "Modernizing the Point-of-Sale Experience",
      "Reimagining Luxury Craftsmanship",
      "Helping Healthier Habits Stick"
    ];

    const insights = [
      "When Human Connection Meets AI",
      "Writing the Future of AI",
      "Amplifying Clinical Care with AI",
      "The Future of Customer Experience",
      "Next-Gen Contact Centers: Powered by AI",
      "From Complexity to Clarity"
    ];

    const principles = [
      "Challenge the status quo",
      "Fuse art & science to make ideas real",
      "Create a lasting impact at global scale",
      "Regenerate systems & communities"
    ];

    const howWeWork = [
      { title: "Discover", text: "Map customer realities, business constraints, and growth opportunities in one strategic view." },
      { title: "Design", text: "Translate insight into compelling service concepts, journeys, and digital products." },
      { title: "Build", text: "Prototype, validate, and ship with multidisciplinary squads embedded with client teams." },
      { title: "Scale", text: "Operationalize capability and governance so innovation endures across markets." }
    ];

    function cardImage(index) {
      const imgs = [
        "https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=1200&q=80",
        "https://images.unsplash.com/photo-1552664730-d307ca884978?auto=format&fit=crop&w=1200&q=80",
        "https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1200&q=80",
        "https://images.unsplash.com/photo-1551434678-e076c223a692?auto=format&fit=crop&w=1200&q=80",
        "https://images.unsplash.com/photo-1517048676732-d65bc937f952?auto=format&fit=crop&w=1200&q=80",
        "https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=1200&q=80"
      ];
      return imgs[index % imgs.length];
    }

    const teamTrack = document.getElementById('teamTrack');
    const regionTabs = document.getElementById('regionTabs');

    function renderTeam(region) {
      teamTrack.innerHTML = '';
      (teamByRegion[region] || []).forEach((member) => {
        const card = document.createElement('article');
        card.className = 'team-card';
        card.innerHTML = `
          <div class="team-photo" style="background-image:url('${member.img}')"></div>
          <div class="team-content">
            <p class="team-quote">“${member.quote}”</p>
            <p class="team-name">${member.name}</p>
            <p class="team-meta">${member.title}</p>
            <a href="#" class="team-office">${member.office} Office ↗</a>
          </div>
        `;
        teamTrack.appendChild(card);
      });
      teamTrack.scrollTo({ left: 0, behavior: 'smooth' });
    }

    regionTabs.addEventListener('click', (e) => {
      const btn = e.target.closest('.tab');
      if (!btn) return;
      [...regionTabs.querySelectorAll('.tab')].forEach(tab => tab.classList.remove('active'));
      btn.classList.add('active');
      renderTeam(btn.dataset.region);
    });

    renderTeam('North America');

    const workTrack = document.getElementById('workTrack');
    workProjects.forEach((title, idx) => {
      const item = document.createElement('article');
      item.className = 'project-card';
      item.innerHTML = `
        <div class="project-thumb" style="background-image:url('${cardImage(idx)}')"></div>
        <div class="project-body"><h3>${title}</h3></div>
      `;
      workTrack.appendChild(item);
    });

    const insightsTrack = document.getElementById('insightsTrack');
    insights.forEach((title, idx) => {
      const item = document.createElement('article');
      item.className = 'insight-card';
      item.innerHTML = `
        <div class="insight-thumb" style="background-image:url('${cardImage(idx + 2)}')"></div>
        <div class="insight-body"><h3>${title}</h3></div>
      `;
      insightsTrack.appendChild(item);
    });

    const principlesCards = document.getElementById('principlesCards');
    principles.forEach((p) => {
      const panel = document.createElement('article');
      panel.className = 'panel';
      panel.innerHTML = `<h3>${p}</h3><p>We embed this principle into our strategy, design, and delivery methods for every enterprise engagement.</p>`;
      principlesCards.appendChild(panel);
    });

    const howCards = document.getElementById('howCards');
    howWeWork.forEach((s) => {
      const panel = document.createElement('article');
      panel.className = 'panel';
      panel.innerHTML = `<h3>${s.title}</h3><p>${s.text}</p>`;
      howCards.appendChild(panel);
    });

    const heroTrack = document.getElementById('heroTrack');
    const heroSlides = [...document.querySelectorAll('.hero-slide')];
    const heroDots = document.getElementById('heroDots');
    const heroPrev = document.getElementById('heroPrev');
    const heroNext = document.getElementById('heroNext');
    let heroIndex = 0;

    heroSlides.forEach((_, idx) => {
      const dot = document.createElement('button');
      dot.className = 'dot' + (idx === 0 ? ' active' : '');
      dot.addEventListener('click', () => setHero(idx));
      heroDots.appendChild(dot);
    });

    function setHero(index) {
      heroIndex = (index + heroSlides.length) % heroSlides.length;
      heroTrack.style.transform = `translateX(-${heroIndex * 100}%)`;
      [...heroDots.children].forEach((dot, i) => dot.classList.toggle('active', i === heroIndex));
    }

    heroPrev.addEventListener('click', () => setHero(heroIndex - 1));
    heroNext.addEventListener('click', () => setHero(heroIndex + 1));
    setInterval(() => setHero(heroIndex + 1), 6000);

    let startX = 0;
    heroTrack.addEventListener('touchstart', e => startX = e.touches[0].clientX, { passive: true });
    heroTrack.addEventListener('touchend', e => {
      const dx = e.changedTouches[0].clientX - startX;
      if (Math.abs(dx) > 45) {
        if (dx < 0) setHero(heroIndex + 1);
        else setHero(heroIndex - 1);
      }
    });

    const langBtn = document.getElementById('langBtn');
    const langMenu = document.getElementById('langMenu');
    langBtn.addEventListener('click', () => {
      langMenu.classList.toggle('open');
      langBtn.setAttribute('aria-expanded', String(langMenu.classList.contains('open')));
    });

    langMenu.addEventListener('click', (e) => {
      if (e.target.tagName === 'BUTTON') {
        langBtn.textContent = e.target.textContent + ' ▾';
        langMenu.classList.remove('open');
      }
    });

    document.addEventListener('click', (e) => {
      if (!langMenu.contains(e.target) && !langBtn.contains(e.target)) langMenu.classList.remove('open');
    });

    const cookieBanner = document.getElementById('cookieBanner');
    const cookieChoice = localStorage.getItem('leap-cookie-choice');
    if (!cookieChoice) {
      setTimeout(() => cookieBanner.classList.add('show'), 900);
    }

    cookieBanner.addEventListener('click', (e) => {
      const btn = e.target.closest('button[data-cookie]');
      if (!btn) return;
      localStorage.setItem('leap-cookie-choice', btn.dataset.cookie);
      cookieBanner.classList.remove('show');
    });

    const menuToggle = document.querySelector('.menu-toggle');
    const navLinks = document.getElementById('navLinks');
    menuToggle.addEventListener('click', () => navLinks.classList.toggle('open'));
    navLinks.addEventListener('click', (e) => {
      if (e.target.tagName === 'A') navLinks.classList.remove('open');
    });
  </script>
</body>
